import{_ as t,o as s,c as o,a3 as a}from"./chunks/framework.EROHjkv0.js";const u=JSON.parse('{"title":"Treadmill and history","description":"","frontmatter":{},"headers":[],"relativePath":"docs/treadmill-and-history.md","filePath":"docs/treadmill-and-history.md"}'),r={name:"docs/treadmill-and-history.md"};function i(n,e,d,h,l,c){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="treadmill-and-history" tabindex="-1">Treadmill and history <a class="header-anchor" href="#treadmill-and-history" aria-label="Permalink to &quot;Treadmill and history&quot;">​</a></h1><p>How the <strong>Treadmill</strong> tab records a session and how the <strong>History</strong> tab shows what was done. Both read the same session records (<a href="./architecture#devices">architecture</a>).</p><h2 id="treadmill-bluetooth-ftms" tabindex="-1">Treadmill (Bluetooth FTMS) <a class="header-anchor" href="#treadmill-bluetooth-ftms" aria-label="Permalink to &quot;Treadmill (Bluetooth FTMS)&quot;">​</a></h2><p>The <strong>Treadmill</strong> tab finds a treadmill that speaks the Bluetooth Fitness Machine Service, shows its live readings and records a session, either free or following a treadmill workout (a built-in demo workout is there until the workout builder exists). Recording is read-only: the app never changes the treadmill&#39;s speed or incline yet, though <code>device/ftms</code> already encodes those commands.</p><p>Testing on a new machine: the bottom of the tab lists what the treadmill says it can report and counts any packets the decoder could not read. Treadmills differ in which fields they send, so a metric that never shows up is usually one the machine does not send.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><p>The <strong>History</strong> tab has two views. <strong>Calendar</strong> shows a month, Monday first, with the days you trained filled in; swipe or use the arrows to go back through earlier months. Under it, that month&#39;s sessions are grouped by day, newest first, and tapping a day scrolls the list to it (a day without sessions shows as a rest day). <strong>Stats</strong> shows this week&#39;s and this month&#39;s totals, charts of the last eight weeks (active minutes, treadmill kilometres), the total number of sessions, the longest run and Poulpy&#39;s full octopuses. Each session&#39;s totals (<code>core/stats</code>) are saved next to it when it ends, so the history opens without replaying the event log; sessions recorded before the history existed are summed up once, the first time the tab opens. Sessions can be deleted from their detail screen.</p>',7)])])}const p=t(r,[["render",i]]);export{u as __pageData,p as default};
